import React, { useRef, useState } from "react";
import { AgGridReact } from "ag-grid-react";
import { AGGridTable } from "tabler-react";
import "tabler-react/style.css";
import "ag-grid-community/styles/ag-grid.css";
import "ag-grid-community/styles/ag-theme-balham.css";

export default function TablaDeFondos() {
  const gridRef = useRef(null);
  const [seleccionados, setSeleccionados] = useState([]);
  const [primero, setPrimero] = useState("Sin consultar");
  const filas = [
    { id: "atlas", name: "Atlas", weight: 60 },
    { id: "brisa", name: "Brisa", weight: 40 },
  ];
  const columnas = [
    { header: "Fondo", item: "name", filter: true },
    { header: "Peso (%)", item: "weight", valueFormatter: p => p.value + " %" },
  ];
  return <>
    <AGGridTable ref={gridRef} AgGridReact={AgGridReact}
      dataColumn={columnas} dataRow={filas}
      getRowId={p => p.data.id}
      defaultColDef={{ sortable: true, resizable: true }}
      rowSelection={{ mode: "multiRow", checkboxes: true, headerCheckbox: true, enableClickSelection: true }}
      onSelectionChanged={event => setSeleccionados(event.api.getSelectedRows())}
      onRowClick={row => console.log("Datos de la fila", row)}
      pinnedTopRowData={[{ id: "total", name: "Total", weight: filas.reduce((sum, row) => sum + row.weight, 0) }]}
      search downloadCSV textFileCSV="fondos.csv"
      pageSize={5} paginationPageSizeSelector={[5, 10]}
      listBtn deselectAllBtn deselectAllOptions={{ text: "Limpiar", hidden: false }} />
    <p>Seleccionados: {seleccionados.map(row => row.name).join(", ") || "ninguno"}</p>
    <button type="button" onClick={() => {
      const node = gridRef.current?.getDisplayedRowAtIndex(0);
      setPrimero(node?.data?.name ?? "No hay filas visibles");
    }}>Consultar primera fila visible</button>
    <p>{primero}</p>
  </>;
}

