import React, { useRef, useState } from "react";
import { AgGridReact } from "ag-grid-react";
import { AGGridTable } from "tabler-react";
import "tabler-react/style.css";
import "ag-grid-community/styles/ag-grid.css";
import "ag-grid-community/styles/ag-theme-balham.css";

export default function TablaConFiltroControlado() {
  const ref = useRef(null);
  const [texto, setTexto] = useState("");
  return <>
    <AGGridTable ref={ref} AgGridReact={AgGridReact}
      dataColumn={[{ header: "Fondo", item: "name" }]}
      dataRow={[{ name: "Atlas" }, { name: "Brisa" }]}
      search quickFilterText={texto}
      onHandleChangeFilter={event => setTexto(event.target.value)}
      rowSelection={{ mode: "multiRow", checkboxes: true }} />
    <button type="button" onClick={() => {
      setTexto("");
      ref.current?.api?.deselectAll();
    }}>Limpiar filtro y selección</button>
  </>;
