import React, { useState } from "react";
import { LineChart } from "tabler-react";
import "tabler-react/style.css";

export default function EvolucionDeLaCartera() {
  const [mensaje, setMensaje] = useState("");
  const lines = [
    { name: "Cartera", data: [100, 104, 109], color: "#3676c8" },
    { name: "Referencia", data: [100, 102, 106], color: "#21a48a" },
  ];
  return <>
    <LineChart lines={lines} height="320px" complete
      xAxisData={["Ene", "Feb", "Mar"]}
      selectedOptions={["Cartera", "Referencia"]}
      getLegend={{ Cartera: true, Referencia: true }}
      yAxisMinInterval={1}
      yAxisFormatter={value => String(value)}
      yAxisMinMax={(range, boundary) => boundary === "min"
        ? Math.floor(range.min - 2) : Math.ceil(range.max + 2)}
      tooltipFormatter={items => items.map(item =>
        item.seriesName + ": " + item.value).join("<br/>")}
      download name="evolucion-cartera" title="Descargar imagen"
      onExpand={() => setMensaje("Aquí la aplicación abriría una vista ampliada.")} />
    <p role="status">{mensaje}</p>
  </>;
}

