import React from "react";
import { RadarChart } from "tabler-react";
import "tabler-react/style.css";

export default function CompararPerfiles() {
  const indicator = [
    { name: "Ambiental", max: 100 },
    { name: "Social", max: 100 },
    { name: "Gobierno", max: 100 },
  ];
  return <RadarChart title="Perfil de la cartera" height="340px"
    indicator={indicator} series={[[80, 70, 90], [65, 85, 75]]}
    seriesDataName={["Cartera", "Referencia"]} colors={["#3676c8", "#21a48a"]}
    tooltipFormatter={item => item.name + "<br/>" + item.value.map((value, index) =>
      indicator[index].name + ": " + value).join("<br/>")}
    download downloadName="perfiles" downloadTitle="Descargar imagen" />;
}
